---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Browser session: The agent browsing for you, step by step, with Pause and Take over.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change browser-session.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './browser-session.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" or "clean" draws it in that style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft" or "clean") */
  'data-style'?: 'soft' | 'clean';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', className]} data-c="browser-session" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="bws panel">
  <div class="bws-h"><div class="bws-ht"><b>Pricing research</b><span class="muted bws-st" aria-live="polite"></span></div><div class="bws-ctl"><button class="ib bws-pause" aria-label="Pause" data-tip="Pause"><svg class="i s"><use href="#i-pause"/></svg></button><button class="pill line sm bws-take" aria-pressed="false">Take over</button></div></div>
  <div class="bws-win"><div class="bws-bar"><span class="bws-dots" aria-hidden="true"><i></i><i></i><i></i></span><div class="bws-url"><svg class="i xs"><use href="#i-search"/></svg><span></span></div></div><div class="bws-vp"></div></div>
  <ol class="bws-steps" aria-label="Steps"></ol>
</div>
  </Fragment></div>
</div>
<script>
  import './browser-session.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Browser session ---------- */
/* the agent browsing for you: a small browser frame with the page it is on drawn as a wireframe, the steps under it, and
   Pause and Take over. When the page gets in its way it stops and asks, and with Take over the page is yours to use. Its
   content is 16px from every edge; each step's mark sits in a 16px column on the content's left edge with its words 12px
   after it, and the card grows and shrinks with what it holds (grow()), centred in its stage */
.bws{width:100%;max-width:440px;margin:0 auto;padding:var(--dm-s-4);display:flex;flex-direction:column}
.bws-h{display:flex;align-items:center;justify-content:space-between;gap:var(--dm-s-3);padding-bottom:var(--dm-s-3)}
.bws-ht{display:flex;flex-direction:column;min-width:0}
.bws-ht b{font-weight:500;font-size:14px;line-height:20px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.bws-st{font-size:12.5px;line-height:18px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.bws-st .shim{font-size:inherit}
/* Pause and Take over side by side are the same drawn height (28px) */
.bws-ctl{display:flex;align-items:center;gap:var(--dm-s-1);flex:none}
.bws-pause.ib{width:28px;height:28px}
/* Take over takes the one hover (--dm-row) under the pointer; pressed (the person has the page) it is the accent's tint */
@media (hover:hover) and (pointer:fine){.bws-take.pill.line:not([disabled],[aria-pressed="true"]):hover{background:var(--dm-row)}}
.bws-take[aria-pressed="true"]{background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-accent));box-shadow:none}
.bws-win{border-radius:var(--dm-r-in);border:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);overflow:hidden;transition:border-color .3s}
.bws.you .bws-win{border-color:var(--dm-accent-mark,var(--dm-accent))}
.bws-bar{display:flex;align-items:center;gap:var(--dm-s-2);height:36px;padding:0 var(--dm-s-2) 0 10px;background:var(--dm-wash);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.bws-dots{display:flex;gap:var(--dm-s-1);flex:none}
.bws-dots i{width:7px;height:7px;border-radius:50%;background:var(--dm-faint)}
/* the address bar is a field: slightly rounded corners, never a full pill */
.bws-url{flex:1;min-width:0;display:flex;align-items:center;gap:6px;height:24px;padding:0 var(--dm-s-2);border-radius:var(--dm-r-sm);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:12px;color:var(--dm-fg2)}
.bws-url .i{color:var(--dm-muted)}
.bws-url span{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.bws-vp{position:relative;height:156px;overflow:hidden;background:var(--dm-surface)}
/* the page itself, drawn small: real words where they matter, grey lines for the rest */
/* (17px on the left, off the 4px scale, so the page's table and button words line up with the steps' words under the frame:
   1px of frame edge, 17px, then their own 10px) */
.bws-pg{position:absolute;left:0;right:0;top:0;padding:var(--dm-s-3) var(--dm-s-4) var(--dm-s-3) 17px;display:flex;flex-direction:column;gap:10px;font-size:12px;color:var(--dm-fg2);transition:transform .8s var(--dm-ease)}
.bws-ln{display:block;height:6px;border-radius:3px;background:var(--dm-chip)}
.bws-nav{display:flex;align-items:center;gap:var(--dm-s-3);font-size:11.5px;color:var(--dm-muted);white-space:nowrap}
.bws-nav b{display:flex;align-items:center;gap:var(--dm-s-2);margin-right:auto;font-weight:500;color:var(--dm-fg)}
.bws-nav b::before{content:"";width:12px;height:12px;border-radius:var(--dm-r-xs);background:var(--dm-fg)}
.bws-nav .on{color:var(--dm-fg)}
.bws-hd{font-size:13px;font-weight:500;color:var(--dm-fg)}
.bws-q{display:flex;align-items:center;gap:6px;height:26px;padding:0 10px;border-radius:var(--dm-r-sm);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent);color:var(--dm-fg);white-space:nowrap;overflow:hidden}
.bws-res{display:flex;flex-direction:column;gap:2px;min-width:0}
.bws-res b{font-weight:500;color:var(--dm-pb);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;align-self:flex-start;max-width:100%}
.bws-res span{font-size:11.5px;color:var(--dm-muted)}
.bws-cta{align-self:flex-start;height:22px;padding:0 10px;display:inline-flex;align-items:center;border-radius:var(--dm-r-pill);background:var(--dm-chip);font-size:11.5px;color:var(--dm-fg2)}
.bws-tb{display:flex;flex-direction:column;border-radius:var(--dm-r-sm);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent)}
.bws-tb div{display:flex;justify-content:space-between;gap:var(--dm-s-3);padding:5px 10px;border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.bws-tb div:first-child{border-top:0;font-size:11.5px;color:var(--dm-muted)}
.bws-tb .num{padding:0 var(--dm-s-1);margin:0 -4px;border-radius:var(--dm-r-xs);color:var(--dm-fg);transition:background .3s,color .3s}
/* a price the agent has taken is marked like a highlighter, in the accent tint with the accent as text (a highlight is
   never a solid accent fill) */
.bws-tb .num.hit{background:var(--dm-sel);color:var(--dm-accent-fg,var(--dm-accent))}
/* what the agent is about to press gets a ring, and its own pointer glides there */
.bws-vp .aim{outline:1.5px solid var(--dm-accent-mark,var(--dm-accent));outline-offset:2px;border-radius:var(--dm-r-xs)}
.bws-cur{position:absolute;left:0;top:0;width:14px;height:14px;z-index:2;color:var(--dm-accent-mark,var(--dm-accent));pointer-events:none;opacity:0;transition:transform .7s var(--dm-ease),opacity .2s}
.bws-cur.on{opacity:1}
.bws-cur svg{display:block;width:14px;height:14px;transition:transform .16s var(--dm-ease)}
.bws-cur svg path{fill:currentColor;stroke:var(--dm-surface);stroke-width:1.4;stroke-linejoin:round}
.bws-cur.down svg{transform:scale(.8)}
/* the page's own cookie banner, the thing in the agent's way */
.bws-ck{position:absolute;left:8px;right:8px;bottom:8px;z-index:1;display:flex;align-items:center;gap:6px;padding:6px 6px 6px 10px;border-radius:calc(10px * var(--dm-rk));background:var(--dm-raised);box-shadow:var(--dm-shadow-pop);font-size:12px;color:var(--dm-fg);transform:translateY(calc(100% + 12px));transition:transform .5s var(--dm-ease)}
.bws-ck.on{transform:none}
.bws-ck span{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.bws-ck button{flex:none;height:24px;padding:0 9px;border-radius:var(--dm-r-pill);font-size:11.5px;background:var(--dm-chip);color:var(--dm-fg)}
.bws-ck button+button{background:var(--dm-ink);color:var(--dm-on-ink)}
.bws:not(.you) .bws-ck button{cursor:default}
.bws-steps{list-style:none;margin:0;padding:var(--dm-s-2) 0 0;display:flex;flex-direction:column}
.bws-s{display:flex;align-items:flex-start;gap:var(--dm-s-3);padding:6px 0;font-size:13px;line-height:20px;color:var(--dm-muted)}
.bws-s:last-child{padding-bottom:0}
.bws-s .g{width:16px;height:20px;display:grid;place-items:center;flex:none;color:var(--dm-faint)}
.bws-s .g .spin{width:11px;height:11px;color:var(--dm-accent-mark,var(--dm-accent))}
.bws-s.done{color:var(--dm-fg2)}.bws-s.done .g{color:var(--dm-ok)}
.bws-s.run,.bws-s.wait{color:var(--dm-fg)}
.bws-s .shim{font-size:inherit}
.bws.paused .bws-s .g .spin{animation-play-state:paused;color:var(--dm-muted)}
.bws-t{flex:1;min-width:0;display:flex;flex-direction:column}
.bws-t>span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.bws-t .d{font-size:12px;line-height:18px;color:var(--dm-muted)}
/* the step that waits for you is a warning notice (owner, 18 Nov; Model picker's busy notice is the reference): a faint warning
   tint as wide as the content with 12px inside it, the filled warning sign, the words in the text colours, Take over white and
   then "Allow closing it" (the action that settles it, last, as in Draft review's notice) as .pill.warn */
.bws-s.wait{margin:var(--dm-s-1) 0;padding:var(--dm-s-3);border-radius:var(--dm-r-in);background:color-mix(in srgb,var(--dm-warn-bg) 45%,transparent)}
.bws-wi{width:16px;height:16px;overflow:visible}
.bws-wi .a{fill:var(--dm-warn-mark);stroke:var(--dm-warn-mark);stroke-width:2;stroke-linejoin:round}
.bws-wi .b{fill:none;stroke:var(--dm-surface);stroke-width:2.2;stroke-linecap:round}
.bws-s.wait .d{color:var(--dm-fg2)}
/* the notice's buttons sit under its words, starting where they start */
.bws-ask{display:flex;flex-wrap:wrap;align-items:center;gap:var(--dm-s-2);margin-top:var(--dm-s-2)}
.bws-ask .pill.line{background:var(--dm-surface);color:var(--dm-fg);box-shadow:var(--dm-on-tint-btn)}
@media (hover:hover) and (pointer:fine){.bws-ask .pill.line:hover{box-shadow:var(--dm-on-tint-btn-h)}}
/* once every step is done: the card's footer under a hairline, 16px from it and from the card's bottom edge; a neutral line
   with the green tick on the steps' mark column and its words on theirs, no green fill (owner, 18 Nov) */
.bws-sum{display:flex;align-items:center;gap:var(--dm-s-3);margin-top:var(--dm-s-4);padding-top:var(--dm-s-4);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:13px;line-height:20px;color:var(--dm-fg2)}
.bws-sum svg{color:var(--dm-ok);flex:none;box-sizing:content-box;padding:0 2px}
.bws-sum span{min-width:0}
/* Clean (owner, 17 and 18 Nov): the content 16px in from every edge, Take over Clean's flat secondary (pressed, it takes the
   stronger neutral fill), ticks in the vivid green, the notice's Take over flat on the tint, and the line once it is done an
   off-white foot strip, its words 16px from its hairline and the card's bottom edge */
:root[data-style="clean"] .bws-ht b,:root [data-style="clean"] .bws-ht b,:root [data-style="clean"].bws-ht b{letter-spacing:-.01em}
:root[data-style="clean"] .bws-take.pill.line[aria-pressed="true"],:root [data-style="clean"] .bws-take.pill.line[aria-pressed="true"],:root [data-style="clean"].bws-take.pill.line[aria-pressed="true"]{color:var(--dm-fg);background:linear-gradient(var(--dm-row-on),var(--dm-row-on)),linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth)}
:root[data-style="clean"] .bws-s.done .g,:root [data-style="clean"] .bws-s.done .g,:root [data-style="clean"].bws-s.done .g,:root[data-style="clean"] .bws-sum svg,:root [data-style="clean"] .bws-sum svg,:root [data-style="clean"].bws-sum svg{color:var(--dm-ok-mark)}
:root[data-style="clean"] .bws-ask .pill.line,:root [data-style="clean"] .bws-ask .pill.line,:root [data-style="clean"].bws-ask .pill.line{color:var(--dm-fg);background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .bws-ask .pill.line:hover,:root [data-style="clean"] .bws-ask .pill.line:hover,:root [data-style="clean"].bws-ask .pill.line:hover{box-shadow:var(--dm-btn2-hover)}}
:root[data-style="clean"] .bws-ask .pill.line:active,:root [data-style="clean"] .bws-ask .pill.line:active,:root [data-style="clean"].bws-ask .pill.line:active{box-shadow:var(--dm-btn2-press)}
:root[data-style="clean"] .bws-sum,:root [data-style="clean"] .bws-sum,:root [data-style="clean"].bws-sum{margin:var(--dm-s-4) -16px -16px;padding:calc(var(--dm-strip-y) + 5px) 16px;line-height:18px;background:var(--dm-strip);border-top:1px solid var(--dm-line);border-radius:0 0 var(--dm-r-card) var(--dm-r-card)}
:root[data-style="clean"] .bws.growing,:root [data-style="clean"] .bws.growing,:root [data-style="clean"].bws.growing{overflow-clip-margin:0px}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, enter, grow, html, swap } from '../core/core.js';
DM.def('browser-session', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{pause}', I('pause')).replace('{search}', I('search','xs'));
  const root = $('.bws', r), stEl = $('.bws-st', r), vp = $('.bws-vp', r), url = $('.bws-url', r), list = $('.bws-steps', r);
  const pauseB = $('.bws-pause', r), takeB = $('.bws-take', r);
  // the card grows and shrinks with what it holds (the notice's buttons, the line once it is done), centred in its stage
  c.offs.push(grow(root));
  // the steps the agent planned, and the pages it passes through, drawn small: a search, the site, its pricing page
  const S = [{ t:'Search "northwind pricing"' }, { t:'Open northwind.app' }, { t:'Click "Pricing"' }, { t:'Read the plans table' }, { t:'Extract prices' }];
  const NAV = on => `<div class="bws-nav"><b>Northwind</b><span>Product</span><span data-k="pricing"${on ? ' class="on"' : ''}>Pricing</span><span>Docs</span></div>`;
  const PAGES = {
    search:`<div class="bws-pg"><div class="bws-q">${I('search','xs')}<span>northwind pricing</span></div>
      <div class="bws-res"><b data-k="site">Northwind · Docs your team reads</b><span>northwind.app</span></div>
      <div class="bws-res"><b>Northwind review: is it worth it?</b><span>softwarenotes.io</span></div>
      <div class="bws-res"><b>Northwind alternatives</b><span>stackcompare.com</span></div></div>`,
    home:`<div class="bws-pg">${NAV(false)}<div class="bws-hd">Docs your team actually reads</div><span class="bws-ln" style="width:92%"></span><span class="bws-ln" style="width:68%"></span><span class="bws-cta">Start free</span></div>`,
    pricing:`<div class="bws-pg">${NAV(true)}<div class="bws-hd">Plans and pricing</div><span class="bws-ln" style="width:78%"></span>
      <div class="bws-tb"><div><span>Plan</span><span>Per seat, monthly</span></div><div><span>Starter</span><span class="num">$8</span></div><div><span>Team</span><span class="num">$16</span></div><div><span>Business</span><span class="num">$32</span></div></div><span class="bws-ln" style="width:64%"></span><span class="bws-ln" style="width:40%"></span></div>`
  };
  // a step's mark: a dot while queued, a spinner while it runs, the filled warning sign while it waits for you, a tick once done
  const G = { queued:'<span class="dot"></span>', run:'<span class="spin"></span>', wait:'<svg class="bws-wi" viewBox="0 0 24 24" aria-hidden="true"><path class="a" d="M12 3.6 2.6 19.9h18.8z"/><path class="b" d="M12 9.6v4.4M12 17v.01"/></svg>', done:I('ok','xs') };
  S.forEach(x => { x.el = html(`<li class="bws-s queued"><span class="g">${G.queued}</span><span class="bws-t"><span>${x.t}</span><span class="d" hidden></span></span></li>`); list.appendChild(x.el); });
  function step(i, s, d){
    const x = S[i], de = $('.d', x.el); if (x.s === s && de.textContent === (d || '')) return;
    x.s = s; x.el.className = 'bws-s ' + s; const g = $('.g', x.el); g.innerHTML = G[s]; enter(g);
    // the running step's words are loader text, with the sweep
    $('.bws-t>span', x.el).classList.toggle('shim', s === 'run');
    if (s === 'run' || s === 'wait') x.el.setAttribute('aria-current', 'step'); else x.el.removeAttribute('aria-current');
    if (!d){ de.hidden = true; de.textContent = ''; } else if (de.hidden){ de.textContent = d; de.hidden = false; enter(de); } else swap(de, d);
  }
  // the page's cookie banner waits below the fold of the viewport, and the agent's own pointer above it
  const ck = html('<div class="bws-ck"><span>This site uses cookies</span><button type="button">Reject all</button><button type="button">Accept all</button></div>');
  const cur = html('<span class="bws-cur" aria-hidden="true"><svg viewBox="0 0 14 14"><path d="M2 1.5l9.5 5-4.2 1.2-2 4.3z"/></svg></span>');
  vp.append(ck, cur);
  function page(k, u){
    const old = $('.bws-pg', vp), pg = html(PAGES[k]); vp.insertBefore(pg, ck); if (old) old.remove(); enter(pg);
    $('svg', url).outerHTML = I(k === 'search' ? 'search' : 'lock', 'xs'); swap($('span', url), u);
  }
  // the person can pause the agent or take the page over; either holds it wherever it is, and it waits for them when
  // the page blocks it
  let paused = false, you = false, blocked = false, finished = false, secs = 0, unblock = null;
  const held = () => paused || you;
  async function act(ms){ for (let left = ms; left > 0;){ await c.wait(100); if (!held()) left -= 100; } }
  async function aim(el){
    const v = vp.getBoundingClientRect(), b = el.getBoundingClientRect(), x = b.left - v.left + Math.min(b.width * .5, 36), y = b.top - v.top + b.height * .6;
    if (!cur.classList.contains('on')){ cur.style.transition = 'none'; cur.style.transform = `translate(${x + 30}px,${y + 40}px)`; void cur.offsetWidth; cur.style.transition = ''; cur.classList.add('on'); }
    cur.style.transform = `translate(${x}px,${y}px)`; el.classList.add('aim');
    await act(800); cur.classList.add('down'); await act(200); cur.classList.remove('down'); el.classList.remove('aim');
  }
  const clock = () => Math.floor(secs / 60) + ':' + String(secs % 60).padStart(2, '0');
  stEl.innerHTML = '<span class="m">Browsing</span> · <span class="num ck">0:00</span>';
  c.every(1000, () => { if (!held() && !blocked && !finished){ secs++; $('.ck', stEl).textContent = clock(); } });
  function update(){
    root.classList.toggle('you', you); root.classList.toggle('paused', paused && !you);
    const m = $('.m', stEl), going = !finished && !you && !paused && !blocked; m.classList.toggle('shim', going);
    swap(m, finished ? 'Done' : you ? 'You have control' : paused ? 'Paused' : blocked ? 'Needs you' : 'Browsing');
    const pl = paused ? 'Resume' : 'Pause'; pauseB.innerHTML = I(paused ? 'play' : 'pause'); pauseB.setAttribute('aria-label', pl); pauseB.dataset.tip = pl;
    pauseB.disabled = you || finished; takeB.disabled = finished;
    takeB.setAttribute('aria-pressed', you); takeB.textContent = you ? 'Hand back' : 'Take over';
    // while the person has the page, its buttons are theirs and the agent's pointer steps aside
    vp.inert = !you; cur.style.visibility = you ? 'hidden' : '';
    const ask = $('.bws-ask', r);
    if (blocked && !you && !ask) showAsk(); else if ((!blocked || you) && ask) ask.remove();
    if (blocked) step(3, 'wait', you ? 'Close the banner, then hand back' : 'A cookie banner covers the table');
  }
  function showAsk(){
    // Take over, then the action that settles it, last, as in Draft review's notice
    const ask = html('<div class="bws-ask"><button class="pill line sm bws-you">Take over</button><button class="pill warn sm bws-allow">Allow closing it</button></div>');
    $('.bws-t', S[3].el).appendChild(ask); enter(ask);
    $('.bws-allow', ask).onclick = () => c.run(async () => {
      // the agent closes it the privacy-friendly way, with Reject all
      blocked = false; update(); step(3, 'run', 'Closing the banner');
      await aim($('button', ck)); ck.classList.remove('on'); unblock();
    });
    $('.bws-you', ask).onclick = () => takeB.click();
  }
  pauseB.onclick = () => { paused = !paused; update(); };
  takeB.onclick = () => { you = !you; if (you) paused = false; update(); };
  // with the page in hand, either banner button closes it
  $$('button', ck).forEach(b => b.onclick = () => { if (!you || !blocked) return; ck.classList.remove('on'); blocked = false; update(); unblock(); });
  // the run: search, open the site, go to pricing and scroll to the table, where a cookie banner covers it and the agent
  // asks before touching it. Once it is gone, it reads the table and takes the three prices
  c.run(async () => {
    page('search', 'northwind pricing'); step(0, 'run');
    await act(1800); step(0, 'done'); step(1, 'run');
    await aim($('[data-k="site"]', vp)); page('home', 'northwind.app');
    await act(1200); step(1, 'done'); step(2, 'run');
    await aim($('[data-k="pricing"]', vp)); page('pricing', 'northwind.app/pricing');
    await act(1000); step(2, 'done'); step(3, 'run');
    await act(600);
    const pg = $('.bws-pg', vp); pg.style.transform = `translateY(${-Math.max(0, Math.min(pg.offsetHeight - vp.clientHeight, $('.bws-tb', pg).offsetTop - 8))}px)`;
    await act(1200); ck.classList.add('on'); await act(500);
    blocked = true; update();
    await new Promise(res => { unblock = res; });
    step(3, 'run');
    await act(1400); step(3, 'done', '3 plans, priced per seat'); step(4, 'run', '0 of 3 prices');
    const cells = $$('.bws-tb .num', vp);
    for (let i = 0; i < cells.length; i++){ await aim(cells[i]); cells[i].classList.add('hit'); step(4, 'run', `${i + 1} of 3 prices`); }
    await act(500); cur.classList.remove('on');
    finished = true; step(4, 'done', '$8, $16 and $32 per seat'); update();
    const sm = html(`<div class="bws-sum">${I('ok','xs')}<span>Done · 3 prices saved to Pricing research</span></div>`); list.after(sm); enter(sm);
  });
  update();
  // the preview's story: the agent stops at the cookie banner, the person allows it to close it, and it finishes
  c.story(async s => {
    await s.until(() => $('.bws-allow', r)); await s.beat(3);
    await s.tap($('.bws-allow', r)); s.away();
    await s.until(() => finished); await s.beat(3);
  });
});
